#include <stdio.h>

int main(void) {
    char s[256];
    char st[256];
    int top = 0;
    int ok = 1;
    if (scanf("%255s", s) != 1) {
        return 0;
    }
    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st[top++] = c;
        } else {
            if (top == 0) {
                ok = 0;
                break;
            }
            char o = st[--top];
            if ((c == ')' && o != '(') ||
                (c == ']' && o != '[') ||
                (c == '}' && o != '{')) {
                ok = 0;
                break;
            }
        }
    }
    if (top != 0) {
        ok = 0;
    }
    puts(ok ? "YES" : "NO");
    return 0;
}
